def transform(grid):
    """Stamp the largest nonzero object, including its background, at each isolated pixel."""
    h, w = len(grid), len(grid[0])
    seen = set()
    components = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            comp = []
            while stack:
                rr, cc = stack.pop()
                comp.append((rr, cc))
                for nr, nc in ((rr-1,cc),(rr+1,cc),(rr,cc-1),(rr,cc+1)):
                    if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] != 0 and (nr,nc) not in seen:
                        seen.add((nr,nc))
                        stack.append((nr,nc))
            components.append(comp)
    motif = max(components, key=len)
    r0 = min(r for r,c in motif); r1 = max(r for r,c in motif)
    c0 = min(c for r,c in motif); c1 = max(c for r,c in motif)
    pivot_r = (r0 + r1) // 2
    pivot_c = (c0 + c1) // 2
    out = [row[:] for row in grid]
    targets = [comp[0] for comp in components if len(comp) == 1 and comp is not motif]
    for tr, tc in targets:
        for r in range(r0, r1 + 1):
            for c in range(c0, c1 + 1):
                rr, cc = tr + r - pivot_r, tc + c - pivot_c
                if 0 <= rr < h and 0 <= cc < w:
                    out[rr][cc] = grid[r][c]
    return out
